# ---------------------------------------------------------------- careers
DEPTS = ["Marketing", "Advertising", "Design & Web", "AI", "Video", "Data", "Operations"]


def _j(title, dept, typ, pay, exp, summary, resp, req, nice, tools):
    slug = "".join(c.lower() if c.isalnum() else "-" for c in title)
    while "--" in slug:
        slug = slug.replace("--", "-")
    return dict(slug=slug.strip("-"), title=title, dept=dept, type=typ, pay=pay, exp=exp,
                summary=summary, resp=resp.split("|"), req=req.split("|"),
                nice=nice.split("|"), tools=tools.split("|"))


